<script setup lang="ts">
import { computed, nextTick, onMounted, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import Notice from '../components/Notice.vue'
import LoadingState from '../components/LoadingState.vue'
import ModelRecovery from './ModelRecovery.vue'
import ComparisonResult from './ComparisonResult.vue'
import { v2, writeV2, V2Error } from './api'
import type { Page } from './types'
interface Check { checkId: string; status: string; explanation: string; evidenceRefs: { kind: string; quote?: string; checkId?: string; start: number; end: number }[] }
interface Evaluation { attemptIds?: string[]; id: string; status: string; operationId?: string; protocol?: { requestedModel: string; returnedModel?: string; mock: boolean; parameters: { reasoning_effort: string } }; result?: { checks?: Check[]; suggestions?: string[] } }
interface Attempt { id: string; ordinal: number; revision: number; status: string; answerText: string; effectiveExposure: string; evaluation?: Evaluation }
interface Case { sourceKind?: string; sourceId?: string; questionIndex?: number; context?: string; id: string; question: string; caseVersion: number; mock: boolean; contextOrigin: string; contextTruncated: boolean; priorDialogue: { id: string; role: string; content: string }[]; analysisExposure: string }
interface Comparison { id: string; status: string; comparability: string; scopeNotice: string; leftAnswer: string; rightAnswer: string; result?: Record<string, any>; protocol?: Evaluation['protocol'] }
const route = useRoute(), id = computed(() => String(route.params.id || ''))
const source = ref<Case | null>(null), cases = ref<{ id: string; question: string; caseVersion: number }[]>([]), attempts = ref<Attempt[]>([]), groups = ref<Evaluation[]>([]), active = ref<Attempt | null>(null), comparison = ref<Comparison | null>(null)
const answer = ref(''), declaration = ref('UNKNOWN'), left = ref(''), right = ref(''), leftGroup = ref(''), rightGroup = ref(''), error = ref(''), recovery = ref<V2Error | null>(null), notice = ref(''), busy = ref(false), loading = ref(true), nextCursor = ref<string | null>(null), attemptCursor = ref<string | null>(null), reveal = ref<{ content?: Record<string, any> | any[] } | null>(null), serverText = ref<string | null>(null)
const reviewId = ref(''), comparisonHistory = ref<Comparison[]>([]), comparisonCursor = ref<string | null>(null), groupCursor = ref<string | null>(null), displayedGroup = ref<any>(null)
const contextText = computed(() => { if (source.value?.contextOrigin !== 'CONFIRMED_STORY') return source.value?.context || ''; try { const fs = JSON.parse(source.value.context || '{}'); return Object.values(fs).map((f: any) => f.confirmation?.notApplicable ? `不适用：${f.confirmation.reason}` : f.text).join('\n\n') } catch { return '故事上下文无法读取，请查看来源版本。' } })
const labels: Record<string, string> = { DRAFT: '草稿', IMPORTED: '历史原答 · 规则未知', EVALUATING: '评估中', READY: '评估就绪', FAILED: '评估失败', INTERRUPTED: '评估中断', SUBMITTED: '已提交' }
const exposure: Record<string, string> = { PROVIDED: '解析已提供 · 辅助准备', SEEN: '用户声明看过', NOT_SEEN: '用户声明未看', UNKNOWN: '暴露状态未知' }
watch(answer, value => { if (active.value?.status === 'DRAFT') try { sessionStorage.setItem(`v2:answer:${active.value.id}`, value) } catch { /* 服务端保存不受本页存储影响。 */ } })
function failed(e: unknown) { error.value = e instanceof Error ? e.message : '操作失败，本页文本保留。'; recovery.value = e instanceof V2Error ? e : null }
async function load(cursor = '') { loading.value = true; try { if (!id.value) { const p = await v2<Page<{ id: string; question: string; caseVersion: number }>>(`/practice-cases?limit=20&cursor=${encodeURIComponent(cursor)}`); cases.value = cursor ? [...cases.value, ...p.items] : p.items; nextCursor.value = p.nextCursor } else { source.value = await v2(`/practice-cases/${id.value}`); const p = await v2<Page<Attempt>>(`/practice-cases/${id.value}/attempts?limit=20`); attempts.value = p.items; attemptCursor.value = p.nextCursor; const gp = await v2<Page<Evaluation>>(`/practice-cases/${id.value}/evaluation-groups?limit=20`); groups.value = gp.items || []; groupCursor.value = gp.nextCursor;
      const recent = await v2<{ items?: Attempt[] }>(`/practice-cases/${id.value}/recent-attempts`); const recentItems = recent.items || attempts.value.filter(a => a.status !== 'DRAFT').slice(-2); const merged = new Map(attempts.value.map(a => [a.id, a])); recentItems.forEach(a => merged.set(a.id, a)); attempts.value = [...merged.values()].sort((a, b) => a.ordinal - b.ordinal);
      if ((!left.value || !right.value || left.value === right.value) && recentItems.length) { left.value = (attempts.value.find(a => a.ordinal === 0) || recentItems[0])!.id; right.value = recentItems.at(-1)!.id }
      if (source.value?.sourceKind === 'SESSION') { const r = await v2<{ id: string | null }>(`/review-item-for-source?sessionId=${encodeURIComponent(source.value.sourceId || '')}&questionIndex=${source.value.questionIndex}`); reviewId.value = r.id || '' } } } catch (e) { failed(e) } finally { loading.value = false } }
async function moreAttempts() { const p = await v2<Page<Attempt>>(`/practice-cases/${id.value}/attempts?limit=20&cursor=${encodeURIComponent(attemptCursor.value || '')}`); const known = new Set(attempts.value.map(a => a.id)); attempts.value.push(...p.items.filter(a => !known.has(a.id))); attempts.value.sort((a, b) => a.ordinal - b.ordinal); attemptCursor.value = p.nextCursor }
async function moreGroups() { try { const p = await v2<Page<Evaluation>>(`/practice-cases/${id.value}/evaluation-groups?limit=20&cursor=${encodeURIComponent(groupCursor.value || '')}`); groups.value.push(...p.items); groupCursor.value = p.nextCursor } catch (e) { failed(e) } }
async function histories(more = false) { try { const p = await v2<Page<Comparison>>(`/practice-comparisons?caseId=${id.value}&limit=20&cursor=${encodeURIComponent(more ? comparisonCursor.value || '' : '')}`); comparisonHistory.value = more ? [...comparisonHistory.value, ...p.items] : p.items; comparisonCursor.value = p.nextCursor } catch (e) { failed(e) } }
async function reopenComparison(cid: string) { try { comparison.value = await v2(`/practice-comparisons/${cid}`); if (['FAILED', 'INTERRUPTED', 'RUNNING'].includes(comparison.value!.status)) recovery.value = Object.assign(new V2Error('对照评估尚未完成'), { operationId: (comparison.value as any).operationId }) } catch (e) { failed(e) } }
async function select(a: Attempt) { try { const fresh = await v2<Attempt>(`/practice-attempts/${a.id}`); active.value = fresh; if (['FAILED', 'INTERRUPTED', 'EVALUATING'].includes(fresh.status) && fresh.evaluation?.operationId) recovery.value = Object.assign(new V2Error('评估尚未完成'), { operationId: fresh.evaluation.operationId }); serverText.value = fresh.answerText; answer.value = fresh.status === 'DRAFT' ? sessionStorage.getItem(`v2:answer:${fresh.id}`) ?? fresh.answerText : fresh.answerText } catch (e) { failed(e) } }
async function create() { busy.value = true; error.value = ''; try { const a = await writeV2<Attempt>(`/practice-cases/${id.value}/attempts`, { exposureDeclaration: declaration.value }); attempts.value.push(a); await select(a) } catch (e) { failed(e) } finally { busy.value = false } }
async function save(submit: boolean) { if (!active.value || busy.value) return; const origin = document.activeElement instanceof HTMLButtonElement ? document.activeElement : null; busy.value = true; error.value = ''; recovery.value = null; try { active.value = await writeV2<Attempt>(`/practice-attempts/${active.value.id}/${submit ? 'submit' : 'draft'}`, { answer: answer.value, expectedVersion: active.value.revision }, submit ? 'POST' : 'PUT'); notice.value = submit ? '已封存独立回答并保存评估。' : '草稿已明确保存到本机服务。'; serverText.value = active.value.answerText; await load() } catch (e) { failed(e); try { const saved = await v2<Attempt>(`/practice-attempts/${active.value.id}`); serverText.value = saved.answerText; if (saved.status !== 'DRAFT') active.value = saved } catch { /* 本页文本继续保留。 */ } } finally { busy.value = false; await nextTick(); if (origin?.isConnected && !origin.disabled && (document.activeElement === document.body || document.activeElement === origin)) origin.focus() } }
async function compare(pair: boolean) { busy.value = true; error.value = ''; try { comparison.value = await writeV2('/practice-comparisons', { leftAttemptId: left.value, rightAttemptId: right.value, mode: pair ? 'REEVALUATE_PAIR' : 'COMPARE', ...(leftGroup.value ? { leftEvaluationGroupId: leftGroup.value } : {}), ...(rightGroup.value ? { rightEvaluationGroupId: rightGroup.value } : {}) }); await load() } catch (e) { failed(e) } finally { busy.value = false } }
async function recoverResult() { recovery.value = null; error.value = ''; await load(); if (active.value) await select(active.value); if (comparison.value) await reopenComparison(comparison.value.id) }
async function revealAnalysis() { if (!source.value) return; busy.value = true; try { const c = await v2<Case & { revision: number }>(`/practice-cases/${id.value}`); reveal.value = await writeV2(`/practice-cases/${id.value}/reveal`, { revealKind: 'SOURCE_ANALYSIS', expectedVersion: c.revision }); source.value.analysisExposure = 'PROVIDED' } catch (e) { failed(e) } finally { busy.value = false } }
async function newGroup() { if (!active.value) return; busy.value = true; try { await writeV2(`/practice-cases/${id.value}/evaluation-groups`, { attemptId: active.value.id }); notice.value = '已另存当前协议评估，原有结果保留。'; await load() } catch (e) { failed(e) } finally { busy.value = false } }
onMounted(() => load())
</script>
<template><div class="page v2-page"><div class="page-heading"><h1>{{ id ? '同一道题，再回答一次。' : '独立作答，保留每次变化。' }}</h1><p>原文、评估与解析暴露分别保存。辅助准备只说明文本变化。</p></div><Notice :message="error" kind="error" /><Notice :message="notice" /><ModelRecovery :error="recovery" @recovered="recoverResult" /><LoadingState v-if="loading" label="正在读取作答记录…" />
<template v-if="!id && !loading"><div v-if="!cases.length" class="panel v2-empty"><h2>还没有同题案例</h2><p>在已完成的报告或复习项中，选择一条已有回答的问题开始。</p><RouterLink to="/review" class="btn btn-primary">前往复习队列</RouterLink></div><div v-else class="panel v2-list"><article v-for="c in cases" :key="c.id" class="v2-list-row"><div><span class="tiny muted">案例版本 {{ c.caseVersion }}</span><h2>{{ c.question }}</h2></div><RouterLink :to="`/practice/${c.id}`" class="btn btn-secondary">查看原文与尝试</RouterLink></article></div><button v-if="nextCursor" class="btn btn-secondary" @click="load(nextCursor || '')">加载更多案例</button></template>
<template v-if="source"><div class="panel v2-flow"><div><span v-if="source.mock" class="badge badge-orange">Mock · 仅验证流程</span><span class="badge badge-gray">案例版本 {{ source.caseVersion }}</span><h2>{{ source.question }}</h2></div><p>{{ exposure[source.analysisExposure] || '暴露状态未知' }}。旧资料为会话冻结快照{{ source.contextTruncated ? '，已截断，不能据此断言缺失' : '' }}。</p><details v-if="source.priorDialogue.length"><summary>这道追问的必要前文</summary><div v-for="m in source.priorDialogue" :key="m.id" class="v2-quote"><strong>{{ m.role === 'USER' ? '先前回答' : '先前问题' }}</strong><pre>{{ m.content }}</pre></div></details><button class="text-link" :disabled="busy" @click="revealAnalysis">记录解析已提供并查看来源解析</button><section v-if="reveal"><template v-if="Array.isArray(reveal.content)"><p v-for="(r, i) in reveal.content" :key="i">{{ r.description }}</p></template><template v-else-if="reveal.content"><section v-for="(label, key) in { correct: '原报告正确点', incorrect: '原报告错误', missing: '原报告遗漏', uncertain: '原报告未知', suggestions: '原建议' }" :key="key"><h3>{{ label }}</h3><p v-for="(text, i) in reveal.content[key]" :key="i">{{ text }}</p></section></template><p v-else class="muted">此案例没有来源解析，未补造标准答案。</p></section><details><summary>查看冻结的资料上下文</summary><pre>{{ contextText || '没有补充资料上下文' }}</pre></details></div>
<div class="v2-reading-layout v2-section"><article class="panel v2-flow"><div class="v2-toolbar"><h2>每次回答</h2><label for="exposure">新尝试的用户声明</label><select id="exposure" v-model="declaration"><option value="UNKNOWN">不确定</option><option value="NOT_SEEN">我未看过解析</option><option value="SEEN">我看过解析</option></select></div><button class="btn btn-primary" data-action="new-attempt" :disabled="busy" @click="create">新建独立作答</button><section v-for="a in attempts" :key="a.id" class="v2-quote"><button class="text-link" :data-attempt="a.id" @click="select(a)">{{ a.ordinal === 0 ? '原始回答' : `第 ${a.ordinal} 次新作答` }} · {{ labels[a.status] }}</button><pre>{{ a.answerText || '草稿尚未填写' }}</pre><p class="tiny muted">{{ exposure[a.effectiveExposure] }}</p></section><button v-if="attemptCursor" class="btn btn-secondary" @click="moreAttempts">加载更早尝试</button></article>
<aside class="panel v2-flow"><template v-if="active"><h2>{{ active.status === 'DRAFT' ? '撰写本次回答' : '已封存回答与评估' }}</h2><label for="new-answer">我的新回答</label><textarea id="new-answer" v-model="answer" maxlength="6000" rows="12" :readonly="active.status !== 'DRAFT'" /><p class="tiny muted">{{ answer.length }} / 6000 字符。本页输入暂存；“保存草稿”后可从服务端找回。</p><details v-if="serverText !== null && serverText !== answer"><summary>服务端版本（本页文本保留）</summary><pre>{{ serverText }}</pre></details><template v-if="active.status === 'DRAFT'"><button class="btn btn-secondary" data-action="save-draft" :disabled="busy" @click="save(false)">保存草稿到本机服务</button><button class="btn btn-primary" :disabled="busy || !answer.trim()" @click="save(true)">提交独立回答并调用模型评估</button></template><template v-else><p>{{ labels[active.status] }}</p><RouterLink v-if="reviewId && active.status === 'READY'" :to="{ path: `/review/${reviewId}`, query: { attemptId: active.id } }" class="btn btn-secondary">返回复习项，逐条确认本次观察</RouterLink><div v-if="active.evaluation?.protocol" class="tiny muted">请求模型：{{ active.evaluation.protocol.requestedModel }}；返回模型：{{ active.evaluation.protocol.returnedModel || '服务未提供' }}；思考强度：{{ active.evaluation.protocol.parameters.reasoning_effort || '服务默认' }}</div><div v-for="check in active.evaluation?.result?.checks" :key="check.checkId" class="v2-finding"><strong>{{ { MET: '满足', GAP: '有缺口', UNCERTAIN: '无法判断' }[check.status] }} · {{ check.checkId }}</strong><p>{{ check.explanation }}</p><p v-for="(ref, i) in check.evidenceRefs" :key="i" class="tiny muted">{{ ref.kind === 'QUOTE' ? `回答原文：${ref.quote}` : `全文缺失检查：${ref.checkId}，范围 ${ref.start}–${ref.end}` }}</p></div><p v-for="tip in active.evaluation?.result?.suggestions" :key="tip">{{ tip }}</p><button v-if="active.status !== 'IMPORTED'" class="btn btn-secondary" :disabled="busy" @click="newGroup">按当前协议另建评估组（调用模型）</button></template></template><template v-else><h2>选择一次回答查看详情</h2><p class="muted">旧原答的评分协议保留未知；不会套用当前配置补造历史分数。</p></template></aside></div>
<section class="panel v2-flow v2-section"><h2>两次原文对照</h2><div class="v2-compare-grid"><div v-for="side in ['left', 'right']" :key="side"><label :for="`${side}-attempt`">{{ side === 'left' ? '较早回答' : '本次回答' }}</label><select :id="`${side}-attempt`" :value="side === 'left' ? left : right" @change="side === 'left' ? left = ($event.target as HTMLSelectElement).value : right = ($event.target as HTMLSelectElement).value"><option v-for="a in attempts.filter(a => a.status !== 'DRAFT')" :key="a.id" :value="a.id">{{ a.ordinal === 0 ? '原始回答' : `新作答 ${a.ordinal}` }}</option></select><label :for="`${side}-group`">评估组</label><select :id="`${side}-group`" :value="side === 'left' ? leftGroup : rightGroup" @change="side === 'left' ? leftGroup = ($event.target as HTMLSelectElement).value : rightGroup = ($event.target as HTMLSelectElement).value"><option value="">初始组（旧原答为未知）</option><option v-for="g in groups.filter(g => g.attemptIds?.includes(side === 'left' ? left : right))" :key="g.id" :value="g.id">{{ g.id.slice(0, 8) }} · {{ g.status }}</option></select></div></div><button class="btn btn-secondary" :disabled="busy || !left || !right || left === right" @click="compare(false)">检查比较条件并对照</button><template v-if="comparison"><p><strong>{{ { SAME_PROTOCOL: '同一可见协议', TEXT_ONLY: '仅可比较原文', DIFFERENT_CONTEXT: '题目或上下文不同' }[comparison.comparability] }}</strong></p><p>{{ comparison.scopeNotice }}</p><div class="v2-compare-grid"><div><h3>较早回答</h3><pre>{{ comparison.leftAnswer }}</pre></div><div><h3>本次回答</h3><pre>{{ comparison.rightAnswer }}</pre></div></div><template v-if="comparison.comparability === 'TEXT_ONLY'"><p>可明确发起配对重评，将产生新的共同协议结果，旧记录保留。此操作调用模型服务。</p><button class="btn btn-primary" :disabled="busy" @click="compare(true)">按同一规则重评这两段原文</button></template><details v-if="comparison.result" open><summary>逐项文本变化与依据</summary><ComparisonResult :result="comparison.result" /></details></template><details @toggle="($event.target as HTMLDetailsElement).open && histories()"><summary>查看已保存对照历史</summary><button v-for="h in comparisonHistory" :key="h.id" class="text-link" @click="reopenComparison(h.id)">打开历史对照 · {{ h.comparability === 'TEXT_ONLY' ? '仅原文' : h.comparability === 'DIFFERENT_CONTEXT' ? '上下文不同' : '同协议' }}</button><button v-if="comparisonCursor" class="text-link" @click="histories(true)">加载更多对照</button></details><details><summary>查看独立评估组历史</summary><div v-for="g in groups" :key="g.id"><button class="text-link" @click="v2<any>(`/practice-evaluation-groups/${g.id}`).then(r => displayedGroup = r).catch(failed)">打开评估组 · {{ g.protocol?.requestedModel || '已记录协议' }}</button></div><button v-if="groupCursor" class="text-link" @click="moreGroups">加载更多评估组</button><div v-if="displayedGroup"><p>请求模型：{{ displayedGroup.protocol?.requestedModel }} · 返回模型：{{ displayedGroup.protocol?.returnedModel || '服务未提供' }}</p><div v-for="(ev, i) in displayedGroup.result?.checks ? [displayedGroup.result] : [displayedGroup.result?.leftEvaluation, displayedGroup.result?.rightEvaluation]" :key="i"><p v-for="c in ev?.checks" :key="c.checkId">{{ c.explanation }}</p></div></div></details></section></template></div></template>
